"""One fresh read-only NEBO/notify basis collection. No approval/apply/SQL/network.

The only optional write is one new root0600 proof, O_EXCL via the historical FileOps.
Secret environment values are compared in memory and never printed or saved.
"""
import argparse,base64,hashlib,json,os,re,types
from pathlib import Path
PARENT_SHA='58296305f2ee805f4c390b0676cf8f573ee4d8f3cd9cd6b605c377fb10a71915'
ADAPTER_SHA='6b1fa4b6706592052f18d06c7e4057de122fd2527cfaa6d11106e412673a763e'
PARENT_B64=''
ADAPTER_B64=''

def module(raw,path):
    value=types.ModuleType('exact_readonly_basis');value.__file__=str(path)
    exec(compile(raw,str(path),'exec'),value.__dict__);return value
def main():
    p=argparse.ArgumentParser();p.add_argument('--lease-pid',type=int,required=True);p.add_argument('--save-new-proof',action='store_true');args=p.parse_args()
    try:
        if os.name!='posix' or os.geteuid()!=0:raise ValueError('NATIVE_ROOT_REQUIRED')
        parent=base64.b64decode(PARENT_B64,validate=True);adapter=base64.b64decode(ADAPTER_B64,validate=True)
        if hashlib.sha256(parent).hexdigest()!=PARENT_SHA or hashlib.sha256(adapter).hexdigest()!=ADAPTER_SHA:raise ValueError('EXACT_COLLECTOR_CODE_REQUIRED')
        pm=module(parent,Path('/opt/synapse/releases/palitra-app-20261015/readonly-parent-notify-r2.py'))
        nm=module(adapter,Path('/opt/synapse/releases/palitra-app-20261015/readonly-nebo-basis.py'))
        a,b,prior,current=pm.load_current_notify_r2(args.lease_pid)
        proof=nm.observe(a,b,current,args.lease_pid)
        if args.save_new_proof:
            path=a.exact_path(nm.PROOF_PATH,True)
            if os.path.lexists(path) or os.path.lexists(str(path)+'.pending'):raise ValueError('PROOF_ALREADY_EXISTS_NO_AUTOMATIC_RETRY')
            a.write_new(path,proof);raw=nm.private(a,path)
            if a.decode(raw)!=proof:raise ValueError('NEW_PROOF_BYTES_CHANGED')
        else:raw=(json.dumps(proof,sort_keys=True,separators=(',',':'))+'\n').encode()
        result={'status':'CURRENT_NEBO_NOTIFY_READONLY_NOT_APPROVED','proofSaved':args.save_new_proof,'proofPath':str(nm.PROOF_PATH) if args.save_new_proof else None,'proofSha256':hashlib.sha256(raw).hexdigest(),'parentImage':nm.NEBO_IMAGE,'sourceFiles':len(proof['source']),'staticFiles':len(proof['static']),'chainFiles':len(proof['snapshot']['containers']['content']['files']),'coreSha256':proof['source']['customer-chat.js'],'authSha256':proof['authSupplement']['sha256'],'historicalInvariantRecovered':False,'effectiveEnvironmentValuesExact':True,'artifactPins':proof['artifactPins'],'runtimeWrites':0,'databaseWrites':0}
        print(json.dumps(result,separators=(',',':')));return 0
    except Exception as error:
        code=str(error) if type(error) is ValueError and re.fullmatch('[A-Z][A-Z0-9_]{0,100}',str(error)) else 'READONLY_REBASE_REFUSED'
        print(json.dumps({'status':'READONLY_REBASE_REFUSED_NO_RETRY','code':code,'messageSha256':hashlib.sha256(str(error).encode()).hexdigest(),'runtimeWrites':0,'databaseWrites':0}));return 2
if __name__=='__main__':raise SystemExit(main())
